import os,pathlib,stat

def diagnose_kvm(cpuinfo_text,cpu_support_confirmed,kvm_path="/dev/kvm"):
    if type(cpu_support_confirmed) is not bool:raise ValueError("CPU support confirmation must be boolean")
    if not isinstance(cpuinfo_text,str):raise TypeError("cpuinfo must be text")
    if not cpu_support_confirmed:
        return {"status":"cpu_unsupported","next":"verify host CPU model or use a supported host"}
    flags=set()
    for line in cpuinfo_text.splitlines():
        key,sep,value=line.partition(":")
        if sep and key.strip().lower() in {"flags","features"}:
            flags.update(value.split())
    if not ({"vmx","svm"}&flags):
        return {"status":"firmware_or_hypervisor_hides_virtualization_flag","next":"enable VT-x/AMD-V in firmware and verify nested-virtualization exposure"}
    path=pathlib.Path(kvm_path)
    try:info=path.stat()
    except FileNotFoundError:
        return {"status":"kvm_device_missing","next":"check KVM kernel modules and device-node creation"}
    if not stat.S_ISCHR(info.st_mode):
        return {"status":"kvm_device_not_character_device","next":"inspect the configured device path"}
    if not os.access(path,os.R_OK|os.W_OK):
        return {"status":"kvm_device_permission_denied","next":"grant the service account scoped read/write access"}
    return {"status":"ready","next":"run an isolated VM smoke test"}
```

原题知识说明：
比对CPU能力、固件设置和虚拟化模块日志，确认能力被固件关闭。安排维护窗口按平台支持方式恢复设置并重启，保留原配置；不要把软件模拟性能当恢复成功。验证加速可用、代表虚机启动和性能。

